syntax:
class Base {
    public:
        virtual void foo();  // Declares a virtual function; compiler adds vptr to class layout and generates a vtable entry
};

class Derived : public Base {
    public:
        void foo() override;  // Overrides the virtual function; compiler updates the vtable for Derived to point to this implementation
};

code_example:
#include <iostream>

class Base {
public:
    virtual void foo() {
        std::cout << "Base::foo called" << std::endl;
    }
};

class Derived : public Base {
public:
    void foo() override {
        std::cout << "Derived::foo called" << std::endl;
    }
};

int main() {
    Base* ptr = new Derived();  // ptr points to a Derived object
    ptr->foo();  // Virtual call: resolved at runtime via vtable
    delete ptr;
    return 0;
}
